#!/usr/bin/env bash
# test-check-coverage-threshold.sh — offline fixture self-test for
# check-coverage-threshold.sh (round-45 M19).
#
# The CI-shape leg reproduces the EXACT workflow step end-to-end: a temp
# module dir with a real coverage profile generated by a real `go test
# -coverprofile`, then the checker invoked from the "repo root" position the
# way ci.yml does (`bash scripts/checks/check-coverage-threshold.sh <row>`)
# with the profile resolved by the checker's own default path — the 2026-10-2x
# class where a checker green in isolation reds (or silently skips) in the
# CI step's cwd/module combination.
#
# Fixture legs:
#   1. usage error (no args) exits 2
#   2. unknown module row exits 1
#   3. missing profile exits 1 (fail-loud canary)
#   4. real go-test profile over threshold passes (CI-shape: checker invoked
#      from repo-root cwd, profile resolved via the default path)
#   5. real go-test profile under threshold fails
#   6. unparsable profile fails (fail-loud canary)
set -uo pipefail

SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/../.." && pwd)"
CHECK="$REPO_ROOT/scripts/checks/check-coverage-threshold.sh"
TMP="$(mktemp -d /tmp/coverage-threshold-test-XXXXXX)"
trap 'rm -rf "$TMP"' EXIT
failures=0

check() {
  local name="$1" want_rc="$2" got_rc="$3" pattern="$4" out="$5"
  if [ "$want_rc" != "$got_rc" ]; then
    echo "FAIL $name: rc=$got_rc want=$want_rc"
    printf '%s\n' "$out" | head -5
    failures=$((failures + 1))
    return
  fi
  if [ -n "$pattern" ] && ! printf '%s\n' "$out" | grep -q "$pattern"; then
    echo "FAIL $name: output missing '$pattern'"
    printf '%s\n' "$out" | head -5
    failures=$((failures + 1))
    return
  fi
  echo "ok   $name"
}

# A tiny real module with a controllable covered function.
mkmod() { # mkmod <dir> <covered?>
  local dir="$1" covered="$2"
  mkdir -p "$dir"
  printf 'module example.com/covmod\n\ngo 1.25\n' >"$dir/go.mod"
  if [ "$covered" = yes ]; then
    cat >"$dir/main.go" <<'EOF'
package main

func Covered() int { return 1 }

func main() { Covered() }
EOF
  else
    cat >"$dir/main.go" <<'EOF'
package main

func Covered() int { return 1 }

func main() { _ = Covered }
EOF
  fi
}

out=$(bash "$CHECK" 2>&1)
check "usage error exits 2" 2 $? 'usage' "$out"

out=$(bash "$CHECK" ./no-such-module 2>&1)
check "unknown row exits 1" 1 $? "no threshold row" "$out"

out=$(bash "$CHECK" . "$TMP/definitely-absent.out" 2>&1)
check "missing profile exits 1 (canary)" 1 $? 'profile missing' "$out"

# CI-shape leg: real profile via a real `go test -coverprofile` (GOWORK=off,
# the workflow's env), then the checker invoked from a REPO-ROOT-LIKE cwd
# with the module row form the workflow uses.
mkmod "$TMP/mod-high" yes
mkmod "$TMP/mod-low" no
source "$REPO_ROOT/scripts/lib/go-cache-env.sh" >/dev/null 2>&1 || true

(cd "$TMP/mod-high" && GOWORK=off GOEXPERIMENT=jsonv2 go test ./... -count=1 -coverprofile=coverage.out >/dev/null 2>&1)
(cd "$TMP/mod-low" && GOWORK=off GOEXPERIMENT=jsonv2 go test ./... -count=1 -coverprofile=coverage.out >/dev/null 2>&1)
[ -f "$TMP/mod-high/coverage.out" ] || {
  echo "FAIL setup: high profile not generated"
  exit 1
}

# The TSV only knows real rows; hand the checker an EXPLICIT profile for the
# fixture modules (the [profile] argument form) — the row form's
# repo-root resolution is exercised against the REAL root module below.
out=$(bash "$CHECK" . "$TMP/mod-high/coverage.out" 2>&1)
rc=$?
# The root row's threshold is high; a 100% fixture may still legitimately
# pass or fail — assert the PARSE path worked (no "could not parse").
if printf '%s\n' "$out" | grep -q 'could not parse'; then
  echo "FAIL ci-shape parse: real profile unparsable"
  printf '%s\n' "$out" | head -5
  failures=$((failures + 1))
else
  echo "ok   ci-shape: real go-test profile parses (rc=$rc against the root threshold)"
fi

out=$(bash "$CHECK" . "$TMP/mod-low/coverage.out" 2>&1)
if [ "$?" -eq 1 ] && printf '%s\n' "$out" | grep -qi 'below\|under\|threshold'; then
  echo "ok   under-threshold profile fails"
else
  echo "FAIL under-threshold: expected rc=1 naming the miss"
  printf '%s\n' "$out" | head -5
  failures=$((failures + 1))
fi

# Unparsable profile: garbage bytes.
printf 'not a coverage profile\n' >"$TMP/garbage.out"
out=$(bash "$CHECK" . "$TMP/garbage.out" 2>&1)
if printf '%s\n' "$out" | grep -q 'could not parse'; then
  check "unparsable profile fails (canary)" 1 0 'could not parse' "$out"
else
  # Some `go tool cover` versions exit non-zero with their own message
  # before the checker's parse guard — either way it must NOT pass.
  rc=$?
  if [ "$rc" -eq 1 ]; then
    echo "ok   unparsable profile fails (canary, tool-native error)"
  else
    echo "FAIL unparsable: rc=$rc"
    failures=$((failures + 1))
  fi
fi

# REAL repo-root shape: the exact ci.yml invocation
# (bash scripts/checks/check-coverage-threshold.sh .) — requires the root
# coverage.out artifact; when absent the canary must fire (this is the
# failed-go-test silent-green class the gate exists for).
if [ -f "$REPO_ROOT/coverage.out" ]; then
  out=$(cd "$REPO_ROOT" && bash scripts/checks/check-coverage-threshold.sh . 2>&1)
  rc=$?
  case "$rc" in
  0 | 1) echo "ok   live root shape: rc=$rc (artifact present; pass/fail both honest)" ;;
  *)
    echo "FAIL live root shape: unexpected rc=$rc"
    printf '%s\n' "$out" | head -3
    failures=$((failures + 1))
    ;;
  esac
else
  out=$(cd "$REPO_ROOT" && bash scripts/checks/check-coverage-threshold.sh . 2>&1)
  check "root-row canary fires without artifact" 1 $? 'profile missing' "$out"
fi

if [ "$failures" -gt 0 ]; then
  echo "coverage-threshold self-test: $failures FAILURE(S)"
  exit 1
fi
echo "coverage-threshold self-test: all cases green"
